-- Phase 21: canonical 40-plugin independence/configuration audit infrastructure
create table if not exists public.anaira_plugin_config_audit (
 id uuid primary key default gen_random_uuid(),
 restaurant_id uuid not null,
 plugin_code text not null,
 actor_id uuid,
 config jsonb not null default '{}'::jsonb,
 changed_at timestamptz not null default now()
);
create index if not exists anaira_plugin_config_audit_lookup on public.anaira_plugin_config_audit(restaurant_id,plugin_code,changed_at desc);
alter table public.anaira_plugin_config_audit enable row level security;
drop policy if exists tenant_access on public.anaira_plugin_config_audit;
create policy tenant_access on public.anaira_plugin_config_audit for all to authenticated using (public.anaira_tenant_access(restaurant_id)) with check (public.anaira_tenant_access(restaurant_id));

-- plugin_settings is the canonical tenant settings record; keep RLS enabled and timestamp updates.
alter table public.plugin_settings enable row level security;
drop policy if exists tenant_access on public.plugin_settings;
create policy tenant_access on public.plugin_settings for all to authenticated using (public.anaira_tenant_access(restaurant_id)) with check (public.anaira_tenant_access(restaurant_id));

